fn scale_of(ctx: &Ctx, i: usize) -> f64 {
    let mut cur = Some(i);
    while let Some(k) = cur {
        if let Some(v) = ctx.nodes[k].props.get("scale") {
            let xs = value_nums(&ctx.sheet.env, v);
            if xs.len() == 1 {
                return xs[0];
            }
            return 1.0;
        }
        cur = ctx.nodes[k].parent;
