#!/usr/bin/env python3
# Random floor plans: compare the original and ours; save failing cases.
import random, subprocess, os, sys, tempfile

ORIG = '/workspace/executable'
MINE = '/tmp/bin-fp/executable'
d = tempfile.mkdtemp(dir='/tmp/fp')
seed = int(sys.argv[1]) if len(sys.argv) > 1 else 1
n = int(sys.argv[2]) if len(sys.argv) > 2 else 50
mode = sys.argv[3] if len(sys.argv) > 3 else 'all'
rnd = random.Random(seed)

FIX = {
    'bed': ['queen', 'king', 'double', 'single'],
    'sofa': ['three', 'two', 'one', 'corner', 'stool'],
    'dining': ['six', 'four', 'round'],
    'bath': ['tub', 'shower', 'toilet', 'sink', 'double-sink'],
    'appliance': ['stove', 'fridge', 'washer', 'dishwasher'],
}


def r(a, b, step=0.05):
    k = rnd.randint(0, int((b - a) / step))
    v = a + k * step
    return ('%.2f' % v).rstrip('0').rstrip('.')


def plan():
    out = []
    unit = rnd.choice(['m', 'm', 'm', 'mm'])
    k = 1000 if unit == 'mm' else 1
    def u(v):
        x = float(v) * k
        return ('%.3f' % x).rstrip('0').rstrip('.')
    scale = '0.02' if unit == 'm' else rnd.choice(['0.02', '0.05'])
    root = rnd.random() < 0.6
    head = []
    if root:
        head.append('{ layout: floorplan; unit: %s; scale: %s%s }' % (unit, scale, rnd.choice(['', '; thickness: %s' % u(r(0.1, 0.3))])))
        ind = ''
    else:
        head.append('|floorplan#p| %s{ unit: %s; scale: %s } [' % (rnd.choice(['', '"PLAN" ']), unit, scale))
        ind = '  '
    W = float(r(3, 9, 0.1))
    H = float(r(3, 7, 0.1))
    segs = ['n', 'e', 's', 'w']
    lens = {'n': W, 'e': H, 's': W, 'w': H}
    closed = rnd.random() < 0.7
    if closed:
        draw = 'move(0, 0) right(%s):n down(%s):e left(%s):s close():w' % (u(W), u(H), u(W))
    else:
        draw = 'move(0, 0) right(%s):n down(%s):e left(%s):s' % (u(W), u(H), u(W))
        segs = ['n', 'e', 's']
    out.append(ind + '|wall#o| { draw: %s; } [' % draw)
    used = {}
    for _ in range(rnd.randint(0, 4)):
        s = rnd.choice(segs)
        door = rnd.random() < 0.6
        wd = float(r(0.6, 1.6, 0.05))
        L = lens[s]
        if wd > L - 0.2:
            continue
        at = float(r(0, L - wd, 0.05))
        if at + wd > L:
            continue
        clash = any(not (at + wd <= a0 or at >= a1) for (a0, a1) in used.get(s, []))
        if clash:
            continue
        used.setdefault(s, []).append((at, at + wd))
        props = ['on: %s' % s, 'at: %s' % u(at), 'width: %s' % u(wd)]
        if door:
            sym = rnd.choice(['', '', 'double', 'sliding'])
            if sym:
                props.append('symbol: %s' % sym)
            if sym != 'sliding':
                if rnd.random() < 0.5:
                    props.append('swing: %s' % rnd.choice(['left', 'right']))
                if rnd.random() < 0.5:
                    props.append('hinge: %s' % rnd.choice(['start', 'end']))
        label = rnd.choice(['', '', '"D1" ', '"W2" ', '"X" '])
        out.append(ind + '  |%s| %s{ %s }' % ('door' if door else 'window', label, '; '.join(props)))
    out.append(ind + ']')
    # a partition
    if rnd.random() < 0.6:
        x = float(r(1, W - 1, 0.1))
        y = float(r(1, H - 1, 0.1))
        out.append(ind + '|partition#q| { draw: move(%s, 0) down(%s):face right(%s):side; } [' % (u(x), u(y), u(W - x)))
        if rnd.random() < 0.7 and W - x > 1:
            out.append(ind + '  |door| { on: side; at: %s; width: %s }' % (u(0.1), u(min(0.8, W - x - 0.2))))
        out.append(ind + ']')
    # fixtures
    for _ in range(rnd.randint(0, 5)):
        fam = rnd.choice(list(FIX) + ['stairs'])
        props = []
        if fam == 'stairs':
            props.append('steps: %d' % rnd.randint(2, 15))
        else:
            props.append('symbol: %s' % rnd.choice(FIX[fam]))
        if rnd.random() < 0.4:
            props.append('rotate: %d' % rnd.choice([0, 45, 90, 180, 270, -90, 30]))
        props.append('translate: %s %s' % (u(r(0.5, W - 0.5, 0.05)), u(r(0.5, H - 0.5, 0.05))))
        if rnd.random() < 0.2:
            props.append('width: %s' % u(r(0.4, 3, 0.1)))
        label = rnd.choice(['', '', '"F" ', '"label" '])
        out.append(ind + '|%s| %s{ %s }' % (fam, label, '; '.join(props)))
    if rnd.random() < 0.5:
        out.append(ind + '"ROOM %d m²" { translate: %s %s }' % (rnd.randint(5, 40), u(r(1, W - 1)), u(r(1, H - 1))))
    # dims
    if mode != 'nodims':
        faces = ['w-in', 'e-in', 'w-out', 'e-out', 'w', 'e'] if closed else ['e-in', 'e-out', 'e']
        hfaces = ['n-in', 's-in', 'n-out', 's-out', 'n', 's']
        for _ in range(rnd.randint(0, 4)):
            if rnd.random() < 0.5 and len(faces) >= 2 and closed:
                a, b = rnd.sample(faces, 2)
                side = rnd.choice(['', '', ' { side: top }', ' { side: bottom }'])
            else:
                a, b = rnd.sample(hfaces, 2)
                side = rnd.choice(['', '', ' { side: left }', ' { side: right }'])
            out.append(ind + 'o:%s (-) o:%s%s' % (a, b, side))
    if not root:
        out.append(']')
    return '\n'.join(head + out) + '\n'


ok = 0
fails = []
for t in range(n):
    src = plan()
    f = os.path.join(d, 'case.lini')
    open(f, 'w').write(src)
    r1 = subprocess.run([ORIG, 'case.lini'], capture_output=True, cwd=d)
    r2 = subprocess.run([MINE, 'case.lini'], capture_output=True, cwd=d)
    if r1.stdout == r2.stdout and r1.stderr == r2.stderr and r1.returncode == r2.returncode:
        ok += 1
    else:
        fails.append(src)
print('OK %d / %d' % (ok, n))
if fails:
    open('/tmp/fp/fuzz_fail.txt', 'w').write('\n----\n'.join(fails))
    print('failures saved to /tmp/fp/fuzz_fail.txt')

