// Join one side's offset runs: the inside of a turn trims both runs to where
// they cross; the outside extends their tangents to a mitre (bevelled past
// the miter limit), bridging any arc to it with a straight piece.
fn join_side(cl: &[Seg], side: f64, h: f64, closed: bool) -> Vec<Seg> {
    let mut segs: Vec<Seg> = cl.iter().map(|g| offset_seg(g, side, h)).collect();
    let n = segs.len();
    let mut bridges: Vec<Vec<Seg>> = vec![vec![]; n];
    let joints = if closed { n } else { n.saturating_sub(1) };
    for k in 0..joints {
        let j = (k + 1) % n;
        let p = cl[k].end();
        let (da, db) = match (cl[k].dir_end(), cl[j].dir_start()) {
            (Some(a), Some(b)) => (a, b),
            _ => continue,
        };
        let cross = da.cross(db);
        let dot = da.dot(db);
        let e = segs[k].end();
        let s = segs[j].start();
        if cross.abs() < 1e-9 && dot > 0.0 {
            if !e.near(s) {
                bridges[k].push(Seg::Line { a: e, b: s });
            }
            continue;
        }
        let right_turn = cross > 0.0;
        let outer = (side > 0.0) == right_turn;
        if outer {
            match line_x(e, da, s, db) {
                Some(m) if m.sub(p).len() <= MITER_LIMIT * h + 1e-9 => {
                    if segs[k].is_line() {
                        set_end(&mut segs[k], m);
                    } else {
                        bridges[k].push(Seg::Line { a: e, b: m });
                    }
                    if segs[j].is_line() {
                        set_start(&mut segs[j], m);
                    } else {
                        bridges[k].push(Seg::Line { a: m, b: s });
                    }
                }
                _ => bridges[k].push(Seg::Line { a: e, b: s }),
            }
        } else {
            match cross_point(&segs[k], &segs[j], p) {
                Some(x) => {
                    set_end(&mut segs[k], x);
                    set_start(&mut segs[j], x);
                }
                None => bridges[k].push(Seg::Line { a: e, b: s }),
            }
        }
    }
    let mut out = Vec::new();
    for (k, g) in segs.into_iter().enumerate() {
        out.push(g);
        out.extend(bridges[k].drain(..));
    }
    out
}

