input.old_string:
_ => {
    if n.w > 0.0 && n.h > 0.0 {
        let (cx, cy) = (-n.geo_off.0, -n.geo_off.1);
        let (hw, hh) = (n.w / 2.0, n.h / 2.0);
        let c = [pt(cx - hw, cy - hh), pt(cx + hw, cy - hh), pt(cx + hw, cy + hh), pt(cx - hw, cy + hh)];
        let q: Vec<P> = c.iter().map(|p| apply(&m, *p)).collect();
        for k in 0..4 {
            out.push(Ob::Seg(q[k], q[(k + 1) % 4], sw));
        }
    }
}

input.new_string:
_ => {
    if n.w > 0.0 && n.h > 0.0 {
        let c = apply(&m, pt(-n.geo_off.0, -n.geo_off.1));
        let rot = clean(m[1].atan2(m[0]).to_degrees());
        out.push(Ob::Box(c, n.w / 2.0, n.h / 2.0, rot, sw));
