// Point-in-polygon: 1 inside, 0 on the boundary, -1 outside.
fn poly_side(poly: &[P], p: P) -> i32 {
    let n = poly.len();
    for k in 0..n {
        let a = poly[k];
        let b = poly[(k + 1) % n];
        let ab = b.sub(a);
        let l = ab.len();
        if l == 0.0 {
            continue;
        }
        let d = ab.cross(p.sub(a)).abs() / l;
        let s = p.sub(a).dot(ab) / (l * l);
        if d < 1e-7 && s >= -1e-9 && s <= 1.0 + 1e-9 {
            return 0;
        }
    }
    let mut inside = false;
    for k in 0..n {
        let a = poly[k];
        let b = poly[(k + 1) % n];
        if (a.y > p.y) != (b.y > p.y) {
            let x = a.x + (p.y - a.y) * (b.x - a.x) / (b.y - a.y);
            if p.x < x {
                inside = !inside;
            }
        }
    }
    if inside {
        1
    } else {
        -1
    }
}

// Where a witness line that starts on or inside a polygon first leaves it,
// with the sine of its angle to the edge it leaves by.
fn poly_exit(poly: &[P], a: P, u: P, len: f64) -> Option<(f64, f64)> {
    if poly.len() < 3 || poly_side(poly, a) < 0 {
        return None;
    }
    let n = poly.len();
    let mut ts: Vec<f64> = vec![0.0];
    for k in 0..n {
        let p = poly[k];
        let q = poly[(k + 1) % n];
        let v = q.sub(p);
        let den = u.cross(v);
        let w = p.sub(a);
        if den.abs() < 1e-12 {
            // collinear runs: their ends
            if w.cross(u).abs() < 1e-7 {
                ts.push(w.dot(u));
                ts.push(q.sub(a).dot(u));
            }
            continue;
        }
        let t = w.cross(v) / den;
        let s = w.cross(u) / den;
        if s >= -1e-9 && s <= 1.0 + 1e-9 {
            ts.push(t);
        }
    }
    ts.retain(|t| *t >= -1e-9 && *t <= len + 1e-9);
    ts.sort_by(|x, y| x.partial_cmp(y).unwrap_or(std::cmp::Ordering::Equal));
    ts.dedup_by(|x, y| (*x - *y).abs() < 1e-9);
    for k in 0..ts.len() {
        let t0 = ts[k];
        let t1 = if k + 1 < ts.len() { ts[k + 1] } else { t0 + 1.0 };
        let mid = a.add(u.mul((t0 + t1) / 2.0));
        if poly_side(poly, mid) < 0 {
            if t0 <= 1e-9 {
                return None;
            }
            // the steepest edge through the exit point
            let x = a.add(u.mul(t0));
            let mut best = 0.0f64;
            for j in 0..n {
                let p = poly[j];
                let q = poly[(j + 1) % n];
                let v = q.sub(p);
                let l = v.len();
                if l == 0.0 {
                    continue;
                }
                let d = v.cross(x.sub(p)).abs() / l;
                let s = x.sub(p).dot(v) / (l * l);
                if d < 1e-7 && s >= -1e-9 && s <= 1.0 + 1e-9 {
                    best = best.max((u.cross(v) / l).abs());
                }
            }
            return if best > 1e-9 { Some((t0, best)) } else { None };
        }
    }
    None
}

