#!/usr/bin/env python3
# Broader random floor plans: diagonal/arc walls, multiple walls, styles,
# fonts, labels, nested frames. Compare the original and ours.
import random, subprocess, os, sys, tempfile

ORIG = '/workspace/executable'
MINE = '/tmp/bin-fp/executable'
d = tempfile.mkdtemp(dir='/tmp/fp')
seed = int(sys.argv[1]) if len(sys.argv) > 1 else 1
n = int(sys.argv[2]) if len(sys.argv) > 2 else 50
rnd = random.Random(seed)

FIX = {
    'bed': ['queen', 'king', 'double', 'single'],
    'sofa': ['three', 'two', 'one', 'corner', 'stool'],
    'dining': ['six', 'four', 'round'],
    'bath': ['tub', 'shower', 'toilet', 'sink', 'double-sink'],
    'appliance': ['stove', 'fridge', 'washer', 'dishwasher'],
}


def num(v):
    return ('%.2f' % v).rstrip('0').rstrip('.')


def plan():
    out = []
    scale = rnd.choice(['0.02', '0.02', '0.01', '0.04', '0.025'])
    fs = rnd.choice(['', '', '; font-size: 11', '; font-size: 18'])
    dens = rnd.choice(['', '', '; density: 3'])
    root = rnd.random() < 0.5
    if root:
        out.append('{ layout: floorplan; unit: m; scale: %s%s%s }' % (scale, fs, dens))
        ind = ''
    else:
        out.append('{ %s }' % (fs.strip('; ') or 'gap: 30'))
        wrap = rnd.choice(['', 'row', 'column'])
        if wrap:
            out.append('|%s| [' % wrap)
            out.append('  |box| "side"')
        out.append('|floorplan#f| %s{ unit: m; scale: %s } [' % (rnd.choice(['', '"T" ']), scale))
        ind = '  '
    W = rnd.randint(30, 80) / 10
    H = rnd.randint(30, 60) / 10
    t = rnd.choice(['', '', '; thickness: 0.3', '; thickness: 0.15'])
    style = rnd.choice(['', '', '; fill: --bg; stroke: --stroke-dark; stroke-width: 1'])
    kind = rnd.choice(['box', 'box', 'diag', 'arc', 'L'])
    segs = {}
    if kind == 'box':
        draw = 'move(0, 0) right(%s):n down(%s):e left(%s):s close():w' % (num(W), num(H), num(W))
        segs = {'n': W, 'e': H, 's': W, 'w': H}
    elif kind == 'diag':
        draw = 'move(0, 0) right(%s):n line(1.5, %s):d down(%s):e left(%s):s close():w' % (num(W), num(H / 2), num(H / 2), num(W + 1.5))
        segs = {'n': W, 'e': H / 2, 's': W + 1.5}
    elif kind == 'arc':
        draw = 'move(0, 0) right(%s):n arc(1.2, 90) down(%s):e' % (num(W), num(H))
        segs = {'n': W, 'e': H}
    else:
        draw = 'move(0, 0) right(%s):n down(%s):e left(%s):s' % (num(W), num(H / 2), num(W / 2))
        segs = {'n': W, 'e': H / 2, 's': W / 2}
    out.append(ind + '|wall#o| { draw: %s%s%s } [' % (draw, t, style))
    used = {}
    for _ in range(rnd.randint(0, 4)):
        s = rnd.choice(list(segs))
        L = segs[s]
        wd = rnd.randint(6, 16) / 10
        if wd > L - 0.3:
            continue
        at = rnd.randint(0, int((L - wd) * 10)) / 10
        if any(not (at + wd <= a0 or at >= a1) for (a0, a1) in used.get(s, [])):
            continue
        used.setdefault(s, []).append((at, at + wd))
        door = rnd.random() < 0.6
        props = ['on: %s' % s, 'at: %s' % num(at), 'width: %s' % num(wd)]
        if door:
            sym = rnd.choice(['', '', 'double', 'sliding'])
            if sym:
                props.append('symbol: %s' % sym)
            if sym != 'sliding' and rnd.random() < 0.6:
                props.append('swing: %s' % rnd.choice(['left', 'right']))
            if sym != 'sliding' and rnd.random() < 0.4:
                props.append('hinge: %s' % rnd.choice(['start', 'end']))
        label = rnd.choice(['', '', '"D1" ', '"W" ', '"A\\nB" '])
        out.append(ind + '  |%s| %s{ %s }' % ('door' if door else 'window', label, '; '.join(props)))
    out.append(ind + ']')
    for _ in range(rnd.randint(0, 2)):
        x = rnd.randint(10, int(W * 10) - 10) / 10
        y = rnd.randint(10, int(H * 10) - 10) / 10
        out.append(ind + '|partition| { draw: move(%s, 0) down(%s):a right(%s):b; } [' % (num(x), num(y), num(max(0.5, W - x))))
        if rnd.random() < 0.6 and y > 1.1:
            out.append(ind + '  |door| { on: a; at: 0.1; width: %s; swing: %s }' % (num(min(0.9, y - 0.2)), rnd.choice(['left', 'right'])))
        out.append(ind + ']')
    for _ in range(rnd.randint(0, 5)):
        fam = rnd.choice(list(FIX) + ['stairs'])
        props = ['steps: %d' % rnd.randint(2, 12)] if fam == 'stairs' else ['symbol: %s' % rnd.choice(FIX[fam])]
        if rnd.random() < 0.5:
            props.append('rotate: %d' % rnd.choice([90, 180, 270, -90, 45, 30, 135]))
        props.append('translate: %s %s' % (num(rnd.randint(5, int(W * 10) - 5) / 10), num(rnd.randint(5, int(H * 10) - 5) / 10)))
        if rnd.random() < 0.2:
            props.append('height: %s' % num(rnd.randint(4, 30) / 10))
        label = rnd.choice(['', '', '"F" ', '"Kitchen" ', '"two\\nlines" '])
        out.append(ind + '|%s| %s{ %s }' % (fam, label, '; '.join(props)))
    if rnd.random() < 0.5:
        out.append(ind + '"ROOM" { translate: %s %s }' % (num(W / 2), num(H / 2)))
    if kind in ('box', 'L'):
        hf = ['n-in', 'n-out', 'n'] + (['s-in', 's-out', 's'] if 's' in segs else [])
        vf = ['e-in', 'e-out', 'e'] + (['w-in', 'w-out', 'w'] if 'w' in segs else [])
        for _ in range(rnd.randint(0, 4)):
            if rnd.random() < 0.5 and len(vf) > 3:
                a, b = rnd.sample(vf, 2)
                side = rnd.choice(['', ' { side: top }', ' { side: bottom }'])
            else:
                a, b = rnd.sample(hf, 2)
                side = rnd.choice(['', ' { side: left }', ' { side: right }'])
            lab = rnd.choice(['', '', ' "clear"'])
            out.append(ind + 'o:%s (-) o:%s%s%s' % (a, b, lab, side))
    if not root:
        out.append(']')
        if wrap:
            out.append(']')
    return '\n'.join(out) + '\n'


ok = 0
fails = []
for k in range(n):
    src = plan()
    f = os.path.join(d, 'case.lini')
    open(f, 'w').write(src)
    r1 = subprocess.run([ORIG, 'case.lini'], capture_output=True, cwd=d)
    r2 = subprocess.run([MINE, 'case.lini'], capture_output=True, cwd=d)
    if r1.stdout == r2.stdout and r1.stderr == r2.stderr and r1.returncode == r2.returncode:
        ok += 1
    else:
        fails.append(src)
print('OK %d / %d' % (ok, n))
if fails:
    open('/tmp/fp/fuzz2_fail.txt', 'w').write('\n----\n'.join(fails))

