#!/usr/bin/env python3
# Probe aligned dimensions: print tips, line, text, ext lines for a dim.
import sys, re, math
sys.path.insert(0, '/tmp/fp')
from probe import run, scene


def dims(out):
    s = scene(out)
    ext = re.findall(r'lini-ext-line lini-line" transform="[^"]*">\n\s*<line x1="([^"]*)" y1="([^"]*)" x2="([^"]*)" y2="([^"]*)"', s)
    dl = re.findall(r'lini-dim-line lini-line" transform="[^"]*">\n(?:\s*<mask.*\n)?\s*<line x1="([^"]*)" y1="([^"]*)" x2="([^"]*)" y2="([^"]*)"', s)
    mk = re.findall(r'lini-marker-dim lini-poly" transform="[^"]*">\n\s*<polygon points="([^"]*)"', s)
    tx = re.findall(r'<text class="lini-text lini-dim-text" x="([^"]*)" y="([^"]*)"[^>]*?(?:transform="rotate\(([^ ]*) [^"]*\)")?>([^<]*)<', s)
    return ext, dl, mk, tx


def show(src, args=()):
    o, e, c = run(src, args)
    if c or e:
        print('ERR', c, e.strip()[:300])
    ext, dl, mk, tx = dims(o)
    for k, l in enumerate(dl):
        x1, y1, x2, y2 = map(float, l)
        print('  line (%.3f,%.3f)-(%.3f,%.3f)' % (x1, y1, x2, y2))
    for m in mk:
        print('  tip', m.split()[0])
    for e_ in ext:
        print('  ext', e_)
    for t in tx:
        print('  text', t)
    return o


if __name__ == '__main__':
    show(open(sys.argv[1]).read())

