1595	    c.truncate(2);
1596	    if c.is_empty() {
1597	        return String::new();
1598	    }
1599	    let list: Vec<String> = c.iter().map(|(_, _, n)| format!("':{}'", n)).collect();
1600	    format!("; did you mean {}?", list.join(", "))
1601	}
