1603	// A dimension's end: a wall face (witness from its end nearest the
1604	// dimension), a node's side (from its midpoint) or a point.
1605	#[derive(Clone, Copy, Debug)]
1606	enum Anch {
1607	    Face(P, P),
1608	    Edge(P, P),
1609	    Point(P),
1610	}
1611	
1612	impl Anch {
1613	    fn dir(&self) -> Option<P> {
1614	        match self {
1615	            Anch::Face(a, b) | Anch::Edge(a, b) => Some(b.sub(*a).unit()),
1616	            Anch::Point(_) => None,
1617	        }
1618	    }
1619	}
