1639	// A non-wall node's anchor: its side as an edge, its centre or a corner.
1640	fn node_anchor(ctx: &Ctx, frame: usize, i: usize, anchor: Option<&str>) -> Option<Anch> {
1641	    let n = &ctx.nodes[i];
1642	    let m = frame_matrix(ctx, frame, i);
1643	    let (cx, cy) = (-n.geo_off.0, -n.geo_off.1);
1644	    let (hw, hh) = (n.w / 2.0, n.h / 2.0);
1645	    let p = |x: f64, y: f64| apply(&m, pt(cx + x, cy + y));
1646	    Some(match anchor.unwrap_or("center") {
1647	        "center" => Anch::Point(p(0.0, 0.0)),
1648	        "top" => Anch::Edge(p(-hw, -hh), p(hw, -hh)),
1649	        "bottom" => Anch::Edge(p(-hw, hh), p(hw, hh)),
1650	        "left" => Anch::Edge(p(-hw, -hh), p(-hw, hh)),
1651	        "right" => Anch::Edge(p(hw, -hh), p(hw, hh)),
1652	        "top-left" => Anch::Point(p(-hw, -hh)),
1653	        "top-right" => Anch::Point(p(hw, -hh)),
1654	        "bottom-left" => Anch::Point(p(-hw, hh)),
1655	        "bottom-right" => Anch::Point(p(hw, hh)),
1656	        _ => return None,
1657	    })
1658	}
