1660	// A node side's direction before layout: its rotation chain.
1661	fn side_dir(ctx: &Ctx, i: usize, anchor: Option<&str>) -> Option<P> {
1662	    let mut rot = 0.0;
1663	    let mut cur = Some(i);
1664	    while let Some(k) = cur {
1665	        rot += ctx.comp[k].rotate;
1666	        cur = ctx.nodes[k].parent;
1667	    }
1668	    match anchor {
1669	        Some("top") | Some("bottom") => Some(rot_vec(pt(1.0, 0.0), rot)),
1670	        Some("left") | Some("right") => Some(rot_vec(pt(0.0, 1.0), rot)),
1671	        _ => None,
1672	    }
1673	}
