1675	fn dims_expand(ctx: &mut Ctx) -> Result<(), Diag> {
1676	    'links: for li in 0..ctx.links.len() {
1677	        if ctx.links[li].op != "(-)" {
1678	            continue;
1679	        }
1680	        let frame = match plan_of(ctx, ctx.links[li].container) {
1681	            Some(f) => f,
1682	            None => continue,
1683	        };
1684	        let l = &ctx.links[li];
1685	        // anchors
1686	        let ends = [(l.from, l.from_anchor.clone(), l.from_span), (l.to, l.to_anchor.clone(), l.to_span)];
1687	        let mut dirs: Vec<Option<P>> = Vec::new();
1688	        for (n, anchor, sp) in ends.iter() {
1689	            if !ctx.nodes[*n].is("wall") {
1690	                let a = anchor.as_deref();
1691	                let known = matches!(
1692	                    a,
1693	                    None | Some("center")
1694	                        | Some("top")
1695	                        | Some("bottom")
1696	                        | Some("left")
1697	                        | Some("right")
1698	                        | Some("top-left")
1699	                        | Some("top-right")
1700	                        | Some("bottom-left")
1701	                        | Some("bottom-right")
1702	                );
1703	                if !known || ctx.nodes[*n].prim == Prim::Text {
1704	                    continue 'links;
1705	                }
1706	                dirs.push(side_dir(ctx, *n, a));
1707	                continue;
1708	            }
1709	            let anchor = match anchor {
1710	                Some(a) => a.clone(),
1711	                None => continue 'links,
1712	            };
1713	            match face_of(ctx, *n, &anchor) {
1714	                Ok(Some(f)) => dirs.push(Some(f.1.sub(f.0).unit())),
1715	                Ok(None) => continue 'links,
1716	                Err(_) => {
1717	                    let base = &ctx.sk.base[n];
1718	                    let mut names: Vec<String> = Vec::new();
1719	                    for t in base.tags() {
1720	                        names.push(t.name.clone());
1721	                        if matches!(t.kind, crate::sketch::TagKind::Seg(_)) {
1722	                            names.push(format!("{}-in", t.name));
1723	                            names.push(format!("{}-out", t.name));
1724	                        }
1725	                    }
1726	                    let who = ctx.nodes[*n].id.clone().unwrap_or_default();
1727	                    let msg = format!("no segment ':{}' on '{}'{}", anchor, who, anchor_suggest(&anchor, &names));
1728	                    return Err(Diag::error("layout", &msg, *sp));
1729	                }
1730	            }
1731	        }
1732	        // two points measure along their own line: not drawn here
1733	        let da = match (dirs[0], dirs[1]) {
1734	            (Some(x), _) => x,
1735	            (None, Some(y)) => y,
1736	            (None, None) => continue 'links,
1737	        };
1738	        if let (Some(x), Some(y)) = (dirs[0], dirs[1]) {
1739	            if x.cross(y).abs() > 1e-6 {
1740	                let fs = ctx.links[li].from_span;
1741	                let ts = ctx.links[li].to_span;
1742	                let text = ctx.src.get(fs.start..ts.end).unwrap_or("").to_string();
1743	                let msg = format!("'{}' — perpendicular faces have no shared normal; the angle between edges is '(<)'", text);
1744	                return Err(Diag::error("layout", &msg, Span { start: fs.start, end: ts.end, ..fs }));
1745	            }
1746	        }
1747	        // a slanted run dimensions along itself: not drawn here
1748	        if da.x.abs() > 1e-9 && da.y.abs() > 1e-9 {
1749	            continue 'links;
1750	        }
1751	        let vertical = da.x.abs() > da.y.abs();
1752	        let side = ctx.links[li].style.iter().rev().find(|d| d.name == "side").and_then(|d| ident_of(&d.value)).map(|s| s.to_string());
1753	        if let Some(sd) = &side {
1754	            let ok = if vertical { sd == "left" || sd == "right" } else { sd == "top" || sd == "bottom" };
1755	            if !ok {
1756	                let msg = if vertical { "a vertical dimension stacks on left or right" } else { "a horizontal dimension stacks on top or bottom" };
1757	                return Err(Diag::error("layout", msg, ctx.links[li].span));
1758	            }
1759	        }
1760	        let span = ctx.links[li].span;
1761	        let mut n = Node::new(Prim::Block, vec!["block".to_string()], span);
1762	        n.parent = Some(frame);
1763	        n.scope = ctx.nodes[frame].scope;
1764	        let ni = ctx.nodes.len();
1765	        ctx.nodes.push(n);
1766	        ctx.comp.push(ctx.comp[frame].clone());
1767	        // after the frame's flow children, before its pinned ones
1768	        ctx.nodes[frame].children.push(ni);
1769	        let di = ctx.sk.fp.dims.len();
1770	        ctx.sk.fp.dims.push(Dim { link: li, frame, node: ni, ..Default::default() });
1771	        ctx.sk.fp.parts.insert(ni, Part::Dim(di));
1772	    }
1773	    Ok(())
1774	}
