1776	fn round2(v: f64) -> String {
1777	    let r = (v * 100.0).round() / 100.0;
1778	    let s = format!("{:.2}", r);
1779	    let s = s.trim_end_matches('0').trim_end_matches('.').to_string();
1780	    if s == "-0" {
1781	        "0".to_string()
1782	    } else {
1783	        s
1784	    }
1785	}
