2308	                    continue;
2309	                }
2310	                // into the ellipse's own frame
2311	                let (sn, cs) = (-rot.to_radians()).sin_cos();
2312	                let tr = |p: P| pt(p.x * cs - p.y * sn, p.x * sn + p.y * cs);
2313	                let a0 = tr(a.sub(*c));
2314	                let u0 = tr(u);
2315	                let (ax, ay) = (a0.x / rx, a0.y / ry);
2316	                let (ux, uy) = (u0.x / rx, u0.y / ry);
2317	                let qa = ux * ux + uy * uy;
2318	                let qb = 2.0 * (ax * ux + ay * uy);
2319	                let qc = ax * ax + ay * ay - 1.0;
2320	                let disc = qb * qb - 4.0 * qa * qc;
2321	                if disc < 0.0 || qa == 0.0 {
2322	                    continue;
2323	                }
2324	                let sq = disc.sqrt();
2325	                for t in [(-qb - sq) / (2.0 * qa), (-qb + sq) / (2.0 * qa)] {
2326	                    let x0 = a0.add(u0.mul(t));
2327	                    // the tangent of x²/rx² + y²/ry² = 1 at x0, back in the frame
2328	                    let tl = pt(-x0.y / (ry * ry), x0.x / (rx * rx));
2329	                    let (sn2, cs2) = rot.to_radians().sin_cos();
2330	                    let tangent = pt(tl.x * cs2 - tl.y * sn2, tl.x * sn2 + tl.y * cs2);
2331	                    add(t, tangent, *sw);
2332	                }
2333	            }
2334	        }
2335	    }
2336	    // an outline only touched at a corner opens a gap only where another
2337	    // outline crosses or touches the very same point
2338	    let mut hits: Vec<(f64, f64)> = hits3.iter().map(|(t, h, _)| (t - h, t + h)).collect();
2339	    for (t, half, owner) in &touches {
2340	        let other = hits3.iter().any(|(c, _, o)| o != owner && (c - t).abs() < 1e-6)
2341	            || touches.iter().any(|(c, _, o)| o != owner && (c - t).abs() < 1e-6);
2342	        if other {
2343	            hits.push((t - half, t + half));
2344	        }
2345	    }
2346	    hits.sort_by(|x, y| x.0.partial_cmp(&y.0).unwrap_or(std::cmp::Ordering::Equal));
2347	    let mut merged: Vec<(f64, f64)> = Vec::new();
2348	    for h in hits {
2349	        if let Some(last) = merged.last_mut() {
2350	            if h.0 <= last.1 + 1e-9 {
2351	                last.1 = last.1.max(h.1);
2352	                continue;
2353	            }
2354	        }
2355	        merged.push(h);
2356	    }
2357	    // a gap reaching back to the line's foot never opens: the witness line
2358	    // leaves its own wall there
2359	    merged.retain(|h| h.0 > 2.0);
2360	    merged
2361	}
