2363	// An arrowhead with its tip at p, pointing along d.
2364	fn arrow(p: P, d: P) -> [P; 3] {
2365	    let base = p.sub(d.mul(ARROW_LEN));
2366	    let r = d.right().mul(ARROW_HALF);
2367	    [p, base.add(r), base.sub(r)]
2368	}
