2086	fn mat_mul(m: &[f64; 6], n: &[f64; 6]) -> [f64; 6] {
2087	    [
2088	        m[0] * n[0] + m[2] * n[1],
2089	        m[1] * n[0] + m[3] * n[1],
2090	        m[0] * n[2] + m[2] * n[3],
2091	        m[1] * n[2] + m[3] * n[3],
2092	        m[0] * n[4] + m[2] * n[5] + m[4],
2093	        m[1] * n[4] + m[3] * n[5] + m[5],
2094	    ]
2095	}
