2115	fn obstacles_of(ctx: &Ctx, i: usize, parent: &[f64; 6], out: &mut Vec<(Ob, usize)>) {
2116	    let n = &ctx.nodes[i];
2117	    if n.prim == Prim::Text || ctx.sk.fp.parts.contains_key(&i) || ctx.sk.chrome.contains_key(&i) || ctx.sk.planes.contains_key(&i) {
2118	        return;
2119	    }
2120	    let m = mat_mul(parent, &crate::render::group_matrix(ctx, i));
2121	    let sw = ctx.comp[i].stroke_width;
2122	    if !ctx.sk.wrappers.contains_key(&i) {
2123	        match n.prim {
2124	            Prim::Sketch => {
2125	                if let Some(l) = ctx.sk.laid.get(&i) {
2126	                    for s in &l.shape.subs {
2127	                        let mut segs = s.segs.clone();
2128	                        if s.closed && !s.end().near(s.start) {
2129	                            segs.push(Seg::Line { a: s.end(), b: s.start });
2130	                        }
2131	                        for g in &segs {
2132	                            match g {
2133	                                Seg::Line { a, b } => out.push((Ob::Seg(apply(&m, *a), apply(&m, *b), sw), i)),
2134	                                Seg::Arc { a, c, r, sweep, .. } => {
2135	                                    out.push((Ob::Arc(apply(&m, *c), *r, apply(&m, *a), *sweep, sw), i));
2136	                                }
2137	                                Seg::Cubic { a, b, .. } => out.push((Ob::Seg(apply(&m, *a), apply(&m, *b), sw), i)),
2138	                            }
2139	                        }
2140	                    }
2141	                }
2142	            }
2143	            Prim::Line | Prim::Poly => {
2144	                if let Some(crate::scene::Geo::Points(pts)) = &n.geo {
2145	                    let ps: Vec<P> = pts.iter().map(|&(x, y)| apply(&m, pt(x, y))).collect();
2146	                    for w in ps.windows(2) {
2147	                        out.push((Ob::Seg(w[0], w[1], sw), i));
2148	                    }
2149	                    if n.prim == Prim::Poly && ps.len() > 2 {
2150	                        out.push((Ob::Seg(*ps.last().unwrap(), ps[0], sw), i));
2151	                    }
2152	                }
2153	            }
2154	            Prim::Oval => {
2155	                let c = apply(&m, pt(-n.geo_off.0, -n.geo_off.1));
2156	                let rot = m[1].atan2(m[0]).to_degrees();
2157	                out.push((Ob::Ellipse(c, n.w / 2.0, n.h / 2.0, rot, sw), i));
2158	            }
2159	            _ => {
2160	                if n.w > 0.0 && n.h > 0.0 {
2161	                    let c = apply(&m, pt(-n.geo_off.0, -n.geo_off.1));
2162	                    let rot = clean(m[1].atan2(m[0]).to_degrees());
2163	                    out.push((Ob::Box(c, n.w / 2.0, n.h / 2.0, rot, sw), i));
2164	                }
2165	            }
2166	        }
2167	    }
2168	    for &ch in &n.children {
2169	        obstacles_of(ctx, ch, &m, out);
2170	    }
2171	}
