2178	// Halo gaps along the witness line a → b: (from, to) distances, merged.
2179	fn halo_gaps(obs: &[(Ob, usize)], a: P, b: P) -> Vec<(f64, f64)> {
2180	    let d = b.sub(a);
2181	    let len = d.len();
2182	    if len == 0.0 {
2183	        return vec![];
2184	    }
2185	    let u = d.unit();
2186	    // crossings (t, half, owner) and corner touches (t, half, owner)
2187	    let mut hits3: Vec<(f64, f64, usize)> = Vec::new();
2188	    let mut touches: Vec<(f64, f64, usize)> = Vec::new();
2189	    let half_of = |tangent: P, sw: f64| -> Option<f64> {
2190	        let tl = tangent.len();
2191	        if tl == 0.0 {
2192	            return None;
2193	        }
2194	        let s = (u.cross(tangent) / tl).abs();
2195	        if s < 1e-9 {
2196	            return None;
2197	        }
2198	        Some((sw / 2.0 + 2.0) / s)
2199	    };
2200	    for (ob, owner) in obs {
2201	        let owner = *owner;
2202	        let mut add = |t: f64, tangent: P, sw: f64| {
2203	            if t < -1e-9 || t > len + 1e-9 {
2204	                return;
2205	            }
2206	            if let Some(half) = half_of(tangent, sw) {
2207	                hits3.push((t, half, owner));
2208	            }
2209	        };
2210	        let mut touch = |t: f64, tangent: P, sw: f64| {
2211	            if t < -1e-9 || t > len + 1e-9 {
2212	                return;
2213	            }
2214	            if let Some(half) = half_of(tangent, sw) {
2215	                touches.push((t, half, owner));
2216	            }
2217	        };
2218	        match ob {
2219	            Ob::Box(c, hw, hh, rot, sw) => {
2220	                // in the box's own frame
2221	                let (sn, cs) = (-rot.to_radians()).sin_cos();
2222	                let tr = |p: P| pt(p.x * cs - p.y * sn, p.x * sn + p.y * cs);
2223	                let a0 = tr(a.sub(*c));
2224	                let u0 = tr(u);
2225	                // the two vertical sides, then the two horizontal ones
2226	                for x in [-*hw, *hw] {
2227	                    if u0.x.abs() < 1e-12 {
2228	                        continue;
2229	                    }
2230	                    let t = (x - a0.x) / u0.x;
2231	                    let y = a0.y + u0.y * t;
