// Halo gaps along a → b that reach under one of the dimension's own
// arrowheads (their box, half a pixel out) never open.
fn clear_marks(gaps: Vec<(f64, f64)>, a: P, b: P, marks: &[[P; 3]]) -> Vec<(f64, f64)> {
    if gaps.is_empty() {
        return gaps;
    }
    let u = b.sub(a).unit();
    let mut spans: Vec<(f64, f64)> = Vec::new();
    for m in marks {
        let mut bx = BBox::empty();
        for q in m.iter() {
            bx.add(q.x, q.y);
        }
        let (x0, x1, y0, y1) = (bx.x0 - 0.5, bx.x1 + 0.5, bx.y0 - 0.5, bx.y1 + 0.5);
        // the line's run inside the box
        let mut t0 = f64::NEG_INFINITY;
        let mut t1 = f64::INFINITY;
        for (p, v, lo, hi) in [(a.x, u.x, x0, x1), (a.y, u.y, y0, y1)] {
            if v.abs() < 1e-12 {
                if p <= lo || p >= hi {
                    t0 = f64::INFINITY;
                }
                continue;
            }
            let (s0, s1) = ((lo - p) / v, (hi - p) / v);
            t0 = t0.max(s0.min(s1));
            t1 = t1.min(s0.max(s1));
        }
        if t0 < t1 {
            spans.push((t0, t1));
        }
    }
    gaps.into_iter().filter(|(g0, g1)| !spans.iter().any(|(s0, s1)| g0 < s1 && g1 > s0)).collect()
}

