// A one-bedroom condominium at 1:50 [SPEC 15.11] — the drawing engine wearing
// an architect's vocabulary. A `|wall|` traces the **centreline** and grows the
// 200 mm poché outline around it (`|partition|` is the 100 mm interior define);
// the `|door|` / `|window|` openings ride their wall's `[ ]`, stationed by
// `on:` / `at:`, and clip that outline at the jambs while drawing their own
// leaf, quarter swing arc and sill pair. The six fixture families draw
// true-size bodies — a bed is 1500 × 2000 mm whether the file drafts in `m` or
// `mm` — over a `--bg` fill, so furniture masks the floor it sits on. Counters,
// the island, casework and the balcony deck are plain `|rect|`s and the north
// arrow is a `|sketch|`: SPEC 15.11's parts-library escape.
{
  density: 4;
  |slab::rect| { fill: --bg; stroke: --stroke-dark; stroke-width: 1; }
  |room::block| {
    // the name stacks over the area, both lines centred
    layout: flow; direction: column; align: center; gap: 2; font-size: 11; letter-spacing: 1;
  }
}

|floorplan#unit| "UNIT 12A — ONE BEDROOM · 65 m²" { unit: m; scale: 0.02; } [

  // ── The shell. One centreline loop; `close():west` mitres the seam like any
  // other corner, and every opening below cuts its own gap out of the poché.
  |wall#outer| {
    draw: move(0, 0) right(9.6):north down(6.8):east left(9.6):south
          close():west;
  } [
    |door#entry| "D1" { on: east; at: 1.2; width: 0.95; swing: right; }
    // hinged at the north jamb, opening into the flat — stationed clear of the
    // counter run that now turns the north-east corner
    |door#slider| "D2" { on: west; at: 3.4; width: 2.4; symbol: sliding; }
    // the balcony slider — two panels, no arc
    |window#w1| "W1" { on: west; at: 0.5; width: 2; }
    // the bedroom's own glazing onto the same balcony
  ]
  // North and south are **party walls** against the neighbouring units, so
  // they carry no openings at all — blank poché, the way a condo stacks. Every
  // opening a unit gets is on the entry side (east) or the balcony side (west).

  |partition#bedwall| { draw: move(0, 3.8) right(4.6):head down(3):side; } [
    |door#bed-door| "D3" { on: side; at: 0.4; width: 0.9; swing: right; }
    // 'right' of the pen's travel — the leaf opens into the bedroom
  ]
  |partition#laundry| { draw: move(6, 6.8) up(0.8); }
  // a stub off the south wall: with the bathroom's own west wall it makes the
  // 600 mm open-front alcove the stacked washer/dryer is built into
  |partition#bathwall| { draw: move(9.6, 4) left(2.9):head down(2.8):side; } [
    |door#bath-door| "D4" { on: side; at: 1; width: 0.8; hinge: end; }
    // hung on the far jamb, and 'swing:' left by default — into the bathroom
  ]

  // ── Casework: counters, the island, the wardrobe and the balcony deck.
  |slab#deck| { width: 1.4; height: 6.6; translate: -0.8 3.4; }
  // the balcony runs the west face between the two party walls — its ends stop
  // on their **inner** faces, so the deck is the unit's own and not a strip
  // shared with the neighbours
  |slab| { width: 3.9; height: 0.6; translate: 7.55 0.4; }
  // the kitchen run, against the north wall and into the north-east corner
  |slab| { width: 2; height: 0.9; translate: 7.2 2.05; radius: 4; }
  // the island — `radius:` is core, and sheet-space px: 4 is 50 mm at 1:50
  |slab| { width: 1.1; height: 0.55; translate: 2 1.75; }
  // the coffee table
  |slab| { width: 0.45; height: 0.45; translate: 0.6 4.075; }
  |slab| { width: 0.45; height: 0.45; translate: 3 4.075; }
  // a nightstand either side of the bed's head
  |slab| { width: 0.6; height: 1.4; translate: 4.25 6; }
  // the wardrobe
  |slab| { width: 1.2; height: 0.55; translate: 7.35 4.325; }
  // the vanity top

