  |appliance| { symbol: stove; translate: 6.4 0.4; }
  |appliance| "F" { symbol: fridge; translate: 8.1 0.4; }
  |appliance| "DW" { symbol: dishwasher; translate: 7.7 2.05; }
  |appliance| "W/D" { symbol: washer; translate: 6.35 6.4; }
