  // ── The sheet's own text: room names and authored areas [SPEC 15.11].
  |room| { translate: 2.2 2.75; } [ "LIVING / DINING" "23.9 m²" ]
  |room| { translate: 7.4 3.2; } [ "KITCHEN" ]
  |room| { translate: 3.3 6.1; } [ "BEDROOM" "12.8 m²" ]
  |room| { translate: 5.65 4.6; } [ "HALL" ]
  |room| { translate: 8.35 5.55; } [ "BATH" "7.3 m²" ]
  |room| { translate: -0.8 3.4; } [ "BALCONY" ]

  // The north arrow a plan needs is a `|sketch|` define — SPEC 24 reserves the
  // type, the pen already draws it. It rides the balcony's empty south end,
  // where sheet chrome costs the plan no margin and reads as no fixture.
  |sketch#north| {
    draw: move(-0.8, 5.73) line(0.22, 0.72) line(-0.22, -0.2) line(-0.22, 0.2)
